-- PKG_DMF0008 — 클라우드 현재 상태 점검 (SCM_MGR · 조회 전용 · 변경 없음)
-- VERDICT: PRE=사내 적용 전과 동일 → 해당 파일 적용 / POST=이미 적용 → SKIP / ABSENT=없음 / DIFF=클라우드 본문이 다름 → 전체교체 금지·결과 공유
SET PAGESIZE 200 LINESIZE 300
COLUMN OBJ FORMAT A48
COLUMN VERDICT FORMAT A60

-- [A] 교체 대상 객체
SELECT 'PKG_DMF0008' OBJ, 'PACKAGE' TYP, '10_SPEC.sql' FILE_NM,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0008' AND OBJECT_TYPE = 'PACKAGE') CLOUD_STATUS,
       CASE WHEN NOT EXISTS (SELECT 1 FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0008' AND OBJECT_TYPE = 'PACKAGE') THEN 'ABSENT → ⚠ 기존 객체 부재: 선행 이관 필요'
            WHEN H.S = 211558133737 THEN 'POST → 이미 적용됨(SKIP)'
            WHEN H.S = 210610049829 THEN 'PRE → 적용 대상'
            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PKG_DMF0008' AND TYPE = 'PACKAGE' AND LINE > 1) H;
SELECT 'PKG_DMF0008' OBJ, 'PACKAGE BODY' TYP, '11_BODY.sql' FILE_NM,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0008' AND OBJECT_TYPE = 'PACKAGE BODY') CLOUD_STATUS,
       CASE WHEN NOT EXISTS (SELECT 1 FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0008' AND OBJECT_TYPE = 'PACKAGE BODY') THEN 'ABSENT → ⚠ 기존 객체 부재: 선행 이관 필요'
            WHEN H.S = 3743451553670 THEN 'POST → 이미 적용됨(SKIP)'
            WHEN H.S = 3837171404940 THEN 'PRE → 적용 대상'
            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PKG_DMF0008' AND TYPE = 'PACKAGE BODY' AND LINE > 1) H;

-- [B] DROP 대상 standalone — 멤버 본문 원천. DIFF 면 클라우드에만 있는 수정 → 멤버에 반영 필요(결과 공유)
SELECT 'DMF0008_GET_EDI_MST_REPAIR' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0008_GET_EDI_MST_REPAIR' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (679045282614, 679045282614) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0008_GET_EDI_MST_REPAIR' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'DMF0008_GET_EDI_MST_SUMMARY' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0008_GET_EDI_MST_SUMMARY' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (298429314015, 298429314015) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0008_GET_EDI_MST_SUMMARY' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'DMF0008_GET_SALES_SITE' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0008_GET_SALES_SITE' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (410258466651, 410258466651) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0008_GET_SALES_SITE' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'DMF0008_GET_SALES_SITE_PROJECT_MODEL' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0008_GET_SALES_SITE_PROJECT_MODEL' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (793409740119, 793409740119) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0008_GET_SALES_SITE_PROJECT_MODEL' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'DMF0008_GET_UPDATE_HISTORY' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0008_GET_UPDATE_HISTORY' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (18678917647, 18678917647) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0008_GET_UPDATE_HISTORY' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'DMF0008_SAVE_SALES_SITE_EDI_REPAIR' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0008_SAVE_SALES_SITE_EDI_REPAIR' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (755138634912, 755138634912) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0008_SAVE_SALES_SITE_EDI_REPAIR' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'DMF0008_SAVE_SALES_SITE_PROJECT_EDI_REPAIR' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0008_SAVE_SALES_SITE_PROJECT_EDI_REPAIR' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (759656840980, 759656840980) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'DMF0008_SAVE_SALES_SITE_PROJECT_EDI_REPAIR' AND TYPE = 'PROCEDURE' AND LINE > 1) H;

-- [C] PKG_DMF0008 BODY 의존 객체 — 행이 나오면 MISSING (컴파일 실패 조건)
SELECT COLUMN_VALUE MISSING FROM TABLE(SYS.ODCIVARCHAR2LIST('DM_DNM_EDI_CALLOFF_ITEM', 'DM_MST_CUSTOMER_MODEL', 'DM_MST_ITEM_SINGLE_V', 'FN_GET_DEPT_LIST', 'FN_GET_DEPT_LIST2', 'FN_GET_MULTI_OWNER_NAME', 'GT_GSSI_DMF0008_RESULT_TABLE_1_2', 'GT_GSSI_DMF0008_RESULT_TABLE_2_2', 'PKG_DMF0000', 'PKG_SCM_USER_MNU', 'PR_DM_MST_SITE_CUSTOMER_HIST', 'PR_SCM_SYS_LOG_BATCH', 'SCM_ADM_LOOKUP_MASTER_DETAIL', 'SCM_ADM_USER_M', 'SCM_ARR_SPL_CNT', 'SCM_ARR_SPL_VAL', 'SCM_MST_CITY', 'SCM_MST_COUNTRY', 'SCM_MST_CUSTOMER', 'SCM_MST_PROJECT', 'SCM_MST_SITE', 'SCM_MST_SITE_CUSTOMER', 'SCM_MST_SITE_H', 'SCM_MST_SITE_ITEM', 'SCM_MST_SITE_ITEM_H', 'SCM_MST_SSO_DEPT_INFO', 'SEQ1_SCM_MST_SITE_H', 'SEQ1_SCM_MST_SITE_ITEM_H')) WHERE COLUMN_VALUE NOT IN (SELECT OBJECT_NAME FROM USER_OBJECTS);

-- [D] META 현재값 — API_URL 이 standalone 이면 전환 전, PKG.멤버 면 전환 완료
SELECT API_ID, API_URL FROM SCM_ADM_API_M WHERE API_ID IN ('P_DMF0008_PROJECT_GET', 'P_DMF0008_PROJECT_SAVE', 'P_DMF0008_REPAIR_GET', 'P_DMF0008_REPAIR_SAVE', 'P_DMF0008_SALES_SITE_GET', 'P_DMF0008_SALES_SITE_SAVE', 'P_DMF0008_SITE_GET', 'P_DMF0008_SSPM_GET', 'P_DMF0008_SSPM_SAVE', 'P_DMF0008_SUMMARY_GET', 'P_DMF0008_UPDATE_HISTORY', 'P_DMF0008_UPDATE_HISTORY_GET') ORDER BY API_ID;
SELECT UPPER(PROC_NM) PROC_NM, COUNT(*) CNT FROM SCM_ADM_PROC_M WHERE UPPER(PROC_NM) IN ('DMF0008_GET_EDI_MST_REPAIR', 'DMF0008_GET_EDI_MST_SUMMARY', 'DMF0008_GET_SALES_SITE', 'DMF0008_GET_SALES_SITE_PROJECT_MODEL', 'DMF0008_GET_UPDATE_HISTORY', 'DMF0008_SAVE_SALES_SITE_EDI_REPAIR', 'DMF0008_SAVE_SALES_SITE_PROJECT_EDI_REPAIR') OR PROC_NM IN ('PKG_DMF0008.P_DMF0008_GET_EDI_MST_REPAIR', 'PKG_DMF0008.P_DMF0008_GET_EDI_MST_SUMMARY', 'PKG_DMF0008.P_DMF0008_GET_SALES_SITE', 'PKG_DMF0008.P_DMF0008_GET_SALES_SITE_PROJECT_MODEL', 'PKG_DMF0008.P_DMF0008_GET_UPDATE_HISTORY', 'PKG_DMF0008.P_DMF0008_SAVE_SALES_SITE_EDI_REPAIR', 'PKG_DMF0008.P_DMF0008_SAVE_SALES_SITE_PROJECT_EDI_REPAIR') GROUP BY UPPER(PROC_NM) ORDER BY 1;

-- [E] 앱계정
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM USER_TAB_PRIVS WHERE GRANTEE = 'SCMP_APP' AND TABLE_NAME = 'PKG_DMF0008';
SELECT OWNER, SYNONYM_NAME FROM ALL_SYNONYMS WHERE OWNER = 'SCMP_APP' AND SYNONYM_NAME = 'PKG_DMF0008';
